from model import *
c=C(16,'状态一致性与数据追溯技术','第三篇  关键技术说明')
S(c,'输入身份与派生结果',
P('内容身份的组成','''signature 将 Flight、完整 profile 和 engineVersion 序列化为字符串，用内容比较识别结果是否仍对应当前输入。它不是密码学签名，不提供防伪或身份认证；“签名”在当前代码中表示内容指纹式的相等性依据。

把完整资料包纳入比较，意味着即使 Flight 不变，只要表格、资料版本或其他 profile 内容改变，旧结果也不再自动匹配。这样资料更新不会默默复用旧计算。

JSON.stringify 还保留对象属性顺序。当前对象来自固定构造与正常编辑路径，足以支撑本地比较；若接口接收多语言或不同序列化器生成的对象，应考虑规范化序列化，避免语义相同但属性顺序不同造成无谓失效。''',diagram=D('formula','当前内容身份的具体组成',[['内容包','{ f: Flight, profile: 完整资料包, engine: engineVersion }'],['表示方式','signature = JSON.stringify(内容包)'],['比较目的','当前内容表示 === 确认或结果中的内容表示']]),table=T('变化|签名是否可能变化|业务含义','输入数值改变|是|需要重新确认\n资料表修订|是|需要重新计算\n仅界面主题改变|否|不影响计算\n对象属性顺序不同|可能|当前比较不是规范化哈希')),
P('派生数据不反向成为输入','''重量卡片、风分量和 V2 都从 Flight 派生，不保存为可由用户独立修改的输入字段。否则用户可能同时修改 TOW 和载荷，使两个值无法解释同一计划。当前正向模型用少量基础参数生成一致结果。

原生兼容数据是另一种派生投影。它包含仪表盘需要的字符串和计划字段，但本地计算仍读取 Flight。兼容字段中的航程、时刻和着陆重量有演示占位，不被反读成性能事实。

这形成一条清楚的依赖方向：基础输入生成质量，再生成参考结果和界面摘要。地面变化通过显式提示回到用户核对，避免循环自动覆盖。''',diagram=D('components','单向派生避免多个真值来源',['Flight 基础输入','weights','calculate','原生兼容投影','报告快照','界面摘要'],[(0,1,'质量派生'),(0,2,'参考计算'),(0,3,'确认时映射'),(2,4,'固定结果'),(1,5,'重量卡片'),(3,5,'原生摘要')]),table=T('数据|权威输入源|是否应直接编辑','TOW|Flight 的质量组成|本地模型不直接编辑\nV2|Flight 与 profile|不直接编辑\n原生摘要|确认投影|不作为本地计算回读源\n地面目标|用户地面操作|显式核对后吸收')),
P('失效属于业务状态','''结果失效并不等于删除数值。页面保留旧结果有助于说明“为什么刚才还能导出，现在不能”，而状态层停止当前出口，防止用户把旧数值当作新的计算。notice 提供变化原因，currentResult 提供统一资格判断。

失效原因包括输入编辑、地面目标改变、资料包变化或恢复历史输入。它们的触发位置不同，但最终都破坏“输入、确认、结果一致”的关系。把这一关系集中表达，比每个按钮各自判断某几个字段更可靠。

报告生成前再次检查资格，形成最后一道业务检查。界面上曾显示过绿色结果，不意味着稍后仍可直接生成当前报告。''',diagram=D('state','结果从当前有效转为历史可见',['当前有效结果','输入已编辑','地面目标已变','资料身份已变','旧结果可见但不可导出'],[(0,1,'修改草稿'),(0,2,'地面事件'),(0,3,'资料更新'),(1,4,'签名不匹配'),(2,4,'变化标记'),(3,4,'版本不匹配')]),table=T('层次|失效后的处理|目的','数据层|可保留 Result|支持回看\n状态层|currentResult 返回空|集中资格规则\n页面层|显示原因|解释变化\n报告层|拒绝当前导出|避免脱离上下文使用')) ,refs=['L-F','L-S','L-U'])
S(c,'发布、存储与页面订阅',
P('轻量状态容器的发布机制','''本地扩展使用模块级 state 与 listeners 集合，不另建一套 Redux slice。editFlight 等业务函数替换状态对象后调用 publish，publish 尝试写入 localStorage，再通知全部订阅者。useLocal 把这些通知接入 React 组件状态。

这里的模块级单例适合当前单页面应用。各页面读到同一个对象版本，不需要通过父组件逐层传递航班与历史。订阅在组件卸载时清理，防止离开页面后仍持续更新旧组件。

publish 中的存储是同步 API，因此较大历史会增加主线程工作。当前历史上限 20 条限制了数据规模；若以后保存附件或长时间运行日志，应改用更适合大对象的存储方式。''',diagram=D('sequence','publish 的存储与通知顺序',['业务函数','state','localStorage','listeners'],[(0,1,'替换状态对象'),(0,2,'JSON 序列化并保存'),(2,1,'保存失败时记录原因'),(0,3,'通知全部订阅者'),(3,3,'React 页面更新')]),table=T('设计选择|当前收益|适用边界','模块级单例|页面共享容易|单浏览器上下文\n同步存储|简单确定的写入顺序|对象不宜持续膨胀\n订阅清理|减少遗留更新|按组件生命周期处理\n历史上限|限制保存体积|不替代长期档案')),
P('内存成功与持久化失败','''localStorage 写入可能因容量、浏览器设置或环境限制失败。publish 捕获异常，把原因放入 storageError，再继续通知页面。这样用户仍能使用当前内存对象，并通过文件出口保存工作，而不会因为一次磁盘持久化失败丢失当前屏幕内容。

这种行为也意味着“航班已确认”和“数据已可靠保存到本机”是两个不同事实。页面优先显示存储错误，避免成功通知掩盖未能持久化的问题。刷新前导出 JSON 是当前实现提供的保留方式。

读取失败时保留原存储文本，不自动删除。恢复使用样例初值并显示错误原因，给后续诊断保留原记录。当前只验证恢复对象中的 flight，不能宣称已对历史与所有状态字段完成严格模式校验。''',diagram=D('state','持久化失败时保留内存工作',['内存状态已更新','存储写入成功','存储写入失败','界面继续显示','导出 JSON 保留'],[(0,1,'正常保存'),(0,2,'存储异常'),(1,3,'通知页面'),(2,3,'带 storageError 通知'),(3,4,'用户保留当前输入')]),table=T('情况|内存数据|本机记录','写入成功|最新状态|最新状态\n写入失败|仍为最新状态|可能为旧记录\n读取失败|采用初始可用状态|原文本保留\n文件导出|读取当前 Flight|独立文件副本')),
P('多窗口并发的实际边界','''当前扩展没有监听 storage 事件形成多标签页同步，也没有对本地状态实施跨窗口锁。两个窗口同时打开相同来源时，各有内存 state，并可能先后覆盖同一个 localStorage 键。

这不是单页面内部的订阅问题。listeners 只连接当前 JavaScript 上下文，不能通知另一窗口。对于当前单人本机演示，保持一个主操作窗口能使状态来源更清楚。

扩展设计可以加入 revision 与来源窗口标识，在保存前比较版本，或通过 BroadcastChannel 同步事件。处理冲突时保留用户草稿并提示选择，不宜静默用较晚到达的数据覆盖所有字段。''',diagram=D('components','两个窗口各有内存副本',['窗口 A 内存','窗口 B 内存','同源 localStorage','A 的页面订阅','B 的页面订阅'],[(0,2,'独立写入'),(1,2,'独立写入'),(0,3,'仅通知本窗口'),(1,4,'仅通知本窗口')]),table=T('能力|当前实现|扩展方向','单窗口页面同步|listeners|已具备\n跨窗口事件同步|未建立|BroadcastChannel\n跨窗口版本冲突|未建立|revision 比较\n多人共享计划|未建立|服务端存储和身份')) ,refs=['L-S','L-H'])
S(c,'命令、快照与扩展连接',
P('计划、目标和实际值的三层语义','''Flight 表示用户确认的业务计划，原生地面目标表示运行页面期望达到的状态，宿主当前变量表示运行环境的当前观测。三者可以暂时不同，例如计划燃油已经确认而加油尚未完成。

把计划同步到目标不会自然产生实际状态回执。本地宿主为了展示而写入样例当前值，是开发模式中的特定行为；真实连接时，当前值应来自后端，不能由前端为了让数字一致而覆盖。

三层语义为扩展接口提供明确边界。命令改变目标或请求动作，快照描述实际状态，计划确认记录用户采用哪一组输入进行计算。''',diagram=D('layers','计划、目标、观测的不同责任',['业务计划：用户采用的 Flight 输入','运行目标：期望载荷、燃油或设备状态','实际观测：后端采样得到的当前状态']),table=T('层次|写入者|变化含义','计划|用户与导入流程|计算条件改变\n目标|页面命令或计划同步|运行期望改变\n观测|真实运行后端|实际状态改变\n参考结果|计算服务|对特定计划的派生')),
P('扩展快照的版本和时间','''连接真实后端时，单个字段值不足以表达时效。快照应包含 sessionId、revision、sampledAt 和 quality，分别说明运行会话、顺序、采样时刻和数据质量。页面可以据此判断是否仍在同一飞机会话中，以及新到数据是否比当前更新。

revision 用于同一会话内排序，采样时间用于解释时效，二者不应互相替代。不同机器时钟可能不完全一致，仅比较时间字符串可能错误丢弃有效快照。

当前浏览器宿主是内存 Map，没有这套协议。此处定义的是可与真实接口对齐的扩展数据契约，未声称后端已经实现。''',diagram=D('entity','扩展设计：运行快照信封',[['SnapshotHeader','sessionId','revision','sampledAt / quality'],['AircraftState','position / phase','mass / fuel','systems'],['消费记录','lastRevision','receivedAt','stale 状态']],[(0,1,'标识本次快照'),(0,2,'支持顺序和时效判断')]),table=T('字段|解决的问题|典型判断','sessionId|重启或换机|是否应重建上下文\nrevision|乱序到达|是否更新当前状态\nsampledAt|数据时效|采样距今多久\nquality|值是否可信|正常、估算或不可用')),
P('扩展命令的幂等与回执','''网络超时后重复点击可能把同一请求发送多次。扩展命令使用 commandId 标识一次用户意图，服务端对重复标识返回同一处理结果，可以避免重复执行非幂等动作。简单开关切换比“设置为指定状态”更容易受重复请求影响。

回执应区分接受、拒绝和执行状态，并返回可读原因。页面显示“已接受”时不立即把实际值改为目标值，而等待快照确认状态变化。超时只是没有按时收到回执，不等于后端绝对没有执行。

这种协议适用于燃油、预设和故障等动作，但各动作仍有自己的许可规则。共同信封只统一传输与追踪，不把不同业务都简化成无条件成功。''',diagram=D('sequence','扩展设计：重复请求使用同一命令身份',['页面','连接适配','后端命令表','状态快照'],[(0,1,'commandId + 目标'),(1,2,'提交命令'),(2,1,'接受或拒绝'),(1,2,'超时后相同 ID 重试'),(2,1,'返回同一处理记录'),(3,0,'实际状态更新')]),table=T('状态|界面文字含义|实际值处理','submitted|请求已发送|等待\naccepted|后端已接收|仍等待执行\ncompleted|动作完成回执|结合快照核对\nrejected|未接受及原因|保持当前观测')),
P('断线恢复与陈旧数据','''断线时可继续显示最后快照，但需要同时表达采样时刻和陈旧状态。清空所有值会丢失上下文，继续无标记显示则容易让用户误认为数据仍在更新。计划编辑和后端控制也应按依赖关系分别处理。

恢复连接后先确认会话，再读取完整快照，然后恢复增量更新。如果会话已改变，应撤销旧实际状态关联和未完成命令假设。不能把上一场运行的回执接到新的飞机会话上。

本地离线航班工作台仍可用于准备输入，但来自后端的性能关联需要重新确认。这一原则延续了当前本地结果失效机制，使未来连接保持一致的用户解释。''',diagram=D('state','扩展设计：连接恢复先重建状态基准',['已连接','断线 / 快照陈旧','重连中','会话核对','完整快照就绪'],[(0,1,'连接中断'),(1,2,'恢复连接'),(2,3,'取得会话身份'),(3,4,'读取完整状态'),(4,0,'继续增量更新')]),table=T('功能|断线时可保留|恢复时依据','本地草稿|当前输入|用户确认\n实际状态显示|带陈旧标识的快照|完整新快照\n远端命令|已有命令身份|后台处理记录\n关联计算|历史结果|新状态下重新核对')) ,refs=['L-S','L-H','EFB'],scope='本节前半说明现有数据语义，快照、命令和重连协议属于后端连接扩展设计。')

c=C(17,'运行可靠性与构建实现技术','第三篇  关键技术说明')
S(c,'启动时序与可见故障',
P('宿主初始化先于原生入口','''bootstrap 首先导入 simulator-shim，建立原生入口期望的全局 API，然后设置逻辑画布缩放，再动态导入 A339 EFB。顺序不能反转，因为许多模块在加载时就访问 SimVar 或宿主基类，而不是等到用户点击后才使用。

原生入口完成加载后，再加载演示数据辅助和本地状态模块，执行 initializeLocal，最后发送 AceInitialized 并移除启动提示。启动提示属于页面静态骨架，JavaScript 尚未完成时也能让用户知道正在加载。

入口导入失败时捕获异常，并用 textContent 显示错误内容，避免堆栈或路径被解释成 HTML。可见错误比一个空白画布更容易定位加载阶段。''',diagram=D('sequence','本地启动的依赖顺序',['静态 HTML','bootstrap','宿主及原生入口','本地状态'],[(0,1,'载入脚本并显示提示'),(1,2,'先建立宿主 API'),(1,2,'动态导入 EFB'),(2,3,'initializeLocal'),(1,0,'移除提示或显示错误')]),table=T('阶段|可见状态|关键依赖','HTML 到达|正在加载提示|静态服务\n宿主建立|提示继续存在|适配脚本\n原生入口加载|EFB 组件创建|构建资源及配置\n本地状态初始化|恢复航班|存储与映射')),
P('电源状态与启动显示','''原生 EFB 初始处于 SHUTOFF 时会隐藏主要内容，这在模拟器中可以由外部电源或触摸流程唤醒，但独立浏览器没有相同外部启动条件。应用脚本加载完成后仍可能停留在关闭状态，因此浏览器宿主需要显式建立开机流程。

本地叠加现在在浏览器挂载后进入 LOADING，保留约 2.5 秒原生加载过程，再进入 LOADED。主动休眠或关机时显示明确的“唤醒 EFB”或“开启 EFB”按钮，让用户有可见恢复入口。

该改动限定于浏览器构建，原生模拟器源码基线保留。组件卸载时清理定时器，避免已经离开的组件仍被延迟回调切换状态。''',diagram=D('state','浏览器电源状态的可见入口',['挂载 / SHUTOFF','LOADING','LOADED','STANDBY','可见唤醒按钮'],[(0,1,'浏览器自动开机'),(1,2,'约 2.5 秒后'),(2,3,'用户休眠'),(3,4,'显示入口'),(4,1,'用户唤醒')]),table=T('状态|旧问题|当前浏览器表现','初次 SHUTOFF|可能只有空区域|自动进入加载\nSTANDBY|外部唤醒条件不直观|明确唤醒按钮\n入口异常|难以区分未开机|显示错误文字\n正常 LOADED|主界面|保持原生布局')),
P('逻辑画布与窗口适配','''原生 EFB 以较大的固定设计区域组织控件。本地宿主使用 1430×1000 逻辑画布，并按窗口宽度与扣除底部横幅后的高度求最小比例。instrument 的实际宽高同步设为缩放后的物理尺寸，防止浏览器仍为未缩放元素预留巨大区域。

仅给根元素加 transform 不足以完成适配：内部若继续使用 viewport 单位，就会先按窄窗口收缩一次，再被整体缩放，出现二次压缩。当前宿主把相关全屏尺寸映射到逻辑画布，保持内部坐标一致。

底部横幅高度通过 ResizeObserver 观察，文字换行后重新计算可用空间。因此窄窗口仍能显示整个画布，而不会把横幅覆盖在主要控件上。''',diagram=D('formula','窗口到逻辑画布的缩放',[['可用空间','Aw = viewportWidth；Ah = innerHeight − bannerHeight'],['统一比例','s = max(0.05, min(Aw / 1430, Ah / 1000))'],['物理容器','width = 1430 × s；height = 1000 × s']]),table=T('实现点|作用|对应问题','固定逻辑尺寸|保持内部布局|避免二次压缩\n同步外层宽高|匹配缩放占位|避免溢出\n观察横幅高度|扣除真实底部区域|避免覆盖\n可见启动提示|解释加载状态|避免无信息空白')) ,refs=['L-H','L-B','L-T'])
S(c,'源码叠加与可复现构建',
P('基线、叠加与构建目录','''项目保留 Headwind 与 FlyByWire 的固定源码基线，通过 setup_overlay.py 形成 build-common 和 build-a339x，再注入浏览器适配及本地扩展。生成目录是可再生产物，不能成为唯一的长期修改来源。

integrate_extensions.py 负责把本地页面和业务入口接到已准备的源码结构，prepare_final_host.py 准备静态资源，随后 Vite 构建浏览器产物。每一阶段都有明确输入和输出，失败时由脚本中止后续阶段。

因此维护修改应落到原始扩展或叠加脚本，再重新构建。只编辑 build-common 可能在下次叠加时消失，也难以说明补丁究竟基于哪个上游版本。''',diagram=D('pipeline','从固定源码到浏览器产物',['固定上游源码','setup_overlay','integrate_extensions','prepare_final_host','Vite build','local-efb/dist']),table=T('路径或脚本|性质|维护方式','上游源码|版本基线|保留提交身份\nlocal-extensions|本地业务实现|直接维护\n叠加脚本|适配变更来源|按固定结构应用\nbuild-common / build-a339x|生成源码|可重建\ndist|静态运行产物|由构建生成')),
P('依赖锁定与失败传播','''Build-EFB.ps1 先选择 Python 运行时，再按顺序执行三个准备脚本。每次检查 LASTEXITCODE，非零即抛出明确错误。进入 Headwind 目录后，缺少 Vite 时使用 npm ci 根据锁文件安装依赖，然后执行指定配置的构建。

npm ci 使用现有锁文件，减少依赖解析在不同机器上产生差异。当前安装带有 ignore-scripts 等选项，符合此浏览器构建路径；不能据此概括完整飞机构建的全部依赖需求。

Push-Location 与 finally 中的 Pop-Location 配对，即使构建失败也恢复调用位置。错误传播和目录恢复让重复运行更可控，避免上一次失败改变下一次命令的工作目录。''',diagram=D('sequence','构建脚本的顺序与错误边界',['Build-EFB','Python 准备阶段','依赖安装','Vite'],[(0,1,'逐步执行并检查退出码'),(1,0,'成功后继续'),(0,2,'仅缺少 Vite 时安装'),(2,0,'检查安装结果'),(0,3,'按配置构建'),(3,0,'产物或明确失败')]),table=T('机制|解决的问题|当前实现','锁文件安装|版本漂移|npm ci\n退出码检查|前阶段失败后继续|逐阶段中止\n固定 Vite 配置|入口与别名一致|local-efb/vite.config.mjs\n目录恢复|工作目录遗留|finally 清理')),
P('静态产物与源码交付关系','''启动服务直接读取 dist，不要求每次打开页面都重新编译整个项目。这使普通使用与开发构建分离：用户运行已经验证的产物，开发人员在修改源码后重新生成产物。

交付包同时保留构建脚本、本地扩展、基线信息和必要资源，便于理解产物来源。源码归属和资源许可随其原始文件保留；本技术说明不以“开源”二字代替具体许可内容，也不虚构商业使用授权。

BASELINE.json 在不带 .git 的分发包中提供固定提交信息，但它不是对文件未被修改的密码学证明。文件清单和 SHA256 可以进一步说明此次交付的具体字节内容。''',diagram=D('entity','源码与运行交付的可追溯关系',[['源码包','上游固定基线','本地扩展及脚本','原许可文件'],['构建身份','BASELINE.json','依赖锁文件','构建配置'],['运行产物','dist 静态资源','server.cjs','文件清单及哈希']],[(0,1,'定义构建输入'),(1,2,'生成并标识产物')]),table=T('材料|回答的问题|不替代的材料','基线提交|基于哪版上游|本地变更内容\n扩展源码|增加了什么行为|运行产物\n构建脚本|怎样生成产物|实际生成结果\n文件哈希|本包具体内容|许可证授权')) ,refs=['L-B','L-H','HW','FBW','LIC'])
S(c,'服务生命周期与故障定位',
P('静态服务的路径处理','''server.cjs 只监听 127.0.0.1，默认端口 9697。普通请求解析路径、解码并与 dist 根目录组合，再检查解析后路径仍在该目录范围内。无扩展名路径返回 index.html，以支持应用入口回退。

服务根据扩展名设置 MIME 类型，并使用 no-cache 与 nosniff。no-cache 表示浏览器需要重新验证资源，不等于所有数据都禁止存储。服务没有实现用户账户、多人会话或远程部署权限模型。

健康接口独立返回应用身份，不依赖完整 React 页面渲染。它能确认端口上是预期服务，但不能单独证明所有业务页面已成功加载。''',diagram=D('pipeline','静态请求的路径与类型处理',['HTTP 请求','解析并解码路径','限制在 dist 根目录','入口回退或文件定位','检查普通文件','MIME 与内容返回']),table=T('返回情况|状态|含义','路径无法解码|400|请求格式异常\n越出根目录|403|不允许读取\n文件不存在|404|资源缺失\n有效静态文件|200|返回对应内容\n/__health|200 JSON|服务身份')),
P('重复启动与进程归属','''Start-EFB 先访问健康接口。如果目标应用已在运行，脚本直接报告地址，不再重复启动另一个服务。否则定位 Node、检查 dist/index.html，创建隐藏进程，并把标准输出、错误输出和 PID 写入 logs。

启动后再次访问健康接口，确认端口上的应用身份。这样可以发现端口冲突或启动失败，而不是只看到进程创建成功就认定页面可用。当前脚本使用短等待后检查，不是长期进程监护服务。

Stop-EFB 读取 PID 后核对进程命令行包含本任务 server.cjs 的完整路径，再停止该进程。PID 可能被操作系统重复使用，命令行核对可以降低停止无关进程的风险。''',diagram=D('sequence','启动复用与停止归属核对',['启动脚本','健康接口','Node 进程','PID 与日志'],[(0,1,'先检查已有服务'),(0,2,'必要时隐藏启动'),(2,3,'记录 PID 和输出'),(0,1,'启动后确认身份'),(3,2,'停止时核对命令行')]),table=T('场景|脚本行为|用户结果','已有正确服务|复用|直接打开地址\n缺少产物|停止并说明|运行构建脚本\n端口不是目标应用|身份检查失败|定位端口占用\nPID 已失效|不停止其他进程|显示未匹配说明')),
P('分层定位白屏与资源异常','''页面无内容时，先区分 HTTP 未到达、静态资源缺失、入口脚本异常、电源未进入 LOADED 和布局不可见五种层次。它们可能具有相似视觉表现，但对应证据不同。健康接口正常只能排除其中一部分问题。

静态 HTML 的启动提示表明文档已到达；可见错误文字表明动态导入失败；原生加载画面表明入口已经创建；开机或唤醒按钮表明处于可恢复电源状态。窗口缩放问题则可能在宽窗口正常、窄窗口异常。

这种因果顺序使运行维护说明更具体。用户可以先根据屏幕文字采取刷新、唤醒或重新启动，而开发人员再依据日志定位缺失资源和异常模块。''',diagram=D('layers','从网络到可见界面的诊断层次',['HTTP 服务及健康身份','HTML、JS、CSS、配置资源','入口加载与运行时异常','EFB 电源和页面路由状态','逻辑画布、缩放与可见布局']),table=T('可见现象|优先查看|常见所在层','浏览器无法连接|服务与地址|HTTP\n提示一直加载|资源和脚本错误|静态资源 / 入口\n显示开启或唤醒|电源按钮|EFB 电源\n宽屏正常窄屏异常|缩放和横幅|布局')),
P('验证证据与设计结论的范围','''现有验证包括纯函数算术、离线业务流程、地面布局交互、原生页面采集和启动修复检查。它们分别支持“公式按代码运行”“核心流程可完成”“控件可见”“页面能加载”等结论，不能合并成未经区分的“全部系统验收通过”。

尤其是性能数据适用性、真实设备行为和外部后端连接，需要不同证据。当前算术检查不能替代原始飞机资料核对，浏览器按钮操作不能替代真实仿真状态回执。

运行记录与固定源码提交共同确定实现基线。函数检查结果、界面采集记录和启动日志分别保存，便于根据异常所属层次定位对应证据；扩展连接的可靠性需要在实际连接环境中另外评价。''',diagram=D('lanes','不同证据支持不同结论',[['算术','输入与期望值','函数返回','代码运算一致'],['界面','真实浏览器','交互与截图','页面流程可用'],['外部系统','真实连接与回执','运行状态','需要独立证据']]),table=T('已有记录|支持的结论|范围','25 项算术检查|本地函数边界与结果|软件算术\n14 项离线流程|核心流程不依赖在线计划|浏览器业务\n地面与启动检查|布局和开机修复|指定浏览器环境\n28 个原生入口|页面采集无致命异常|不是完整飞行仿真')) ,refs=['L-H','L-B','L-T'])
